</main></div><script>const search=document.getElementById('sf-search'),allRows=[...document.querySelectorAll('.stock-row')],empty=document.getElementById('sf-empty'),pager=document.getElementById('stock-pagination'),info=document.getElementById('stock-page-info');let page=1;const pageSize=12;function goTo(next){page=next;renderStock();document.querySelector('.stock-table-wrap')?.scrollTo({top:0,behavior:'smooth'})}function button(label,disabled,action,extra=''){const b=document.createElement('button');b.className='page-link '+extra;b.textContent=label;b.type='button';b.disabled=disabled;if(action)b.onclick=action;return b}function renderStock(){const q=(search?.value||'').toLowerCase().trim(),filtered=allRows.filter(row=>!q||row.dataset.search.includes(q)),pages=Math.max(1,Math.ceil(filtered.length/pageSize));page=Math.min(page,pages);allRows.forEach(row=>row.hidden=true);filtered.slice((page-1)*pageSize,page*pageSize).forEach(row=>row.hidden=false);empty.hidden=filtered.length!==0;info.textContent=filtered.length?`MENAMPILKAN ${(page-1)*pageSize+1}–${Math.min(page*pageSize,filtered.length)} DARI ${filtered.length} BARIS`:'TIDAK ADA DATA';pager.innerHTML='';pager.append(button('‹',page===1,()=>goTo(page-1),'pager-arrow'));const visible=[...new Set([1,page-1,page,page+1,pages].filter(n=>n>=1&&n<=pages))].sort((a,b)=>a-b);let previous=0;visible.forEach(n=>{if(previous&&n-previous>1){const dots=document.createElement('span');dots.className='pager-dots';dots.textContent='…';pager.append(dots)}pager.append(button(String(n),false,()=>goTo(n),n===page?'active':''));previous=n});pager.append(button('›',page===pages,()=>goTo(page+1),'pager-arrow'))}search?.addEventListener('input',()=>{page=1;renderStock()});renderStock();</script></body></html>
